mapper.insert:
INSERT INTO knowledge_organization (item_id,owner_id,revision,aliases_json,tags_json,favorite,updated_at)
VALUES (#{id},#{owner},0,JSON_ARRAY(),JSON_ARRAY(),FALSE,#{now})
ON DUPLICATE KEY UPDATE item_id = #{id}

mapper.update:
UPDATE knowledge_organization SET revision = revision + 1, aliases_json = #{aliases}, tags_json = #{tags},
  favorite = #{favorite}, main_note_id = #{mainNoteId}, updated_at = #{now}
WHERE owner_id = #{owner} AND item_id = #{id} AND revision = #{revision}

mapper.select:
SELECT c.id, c.kind, c.item_id, v.title, i.status, c.relation_type, c.direction, c.source_version_id, c.source_version_number, c.line_start, c.line_end, c.excerpt FROM (
SELECT a.id, 'ASSOCIATION' kind, IF(a.concept_id = #{id}, a.note_id, a.concept_id) item_id, NULL relation_type, NULL direction, NULL source_version_id, NULL source_version_number, NULL line_start, NULL line_end, NULL excerpt FROM knowledge_concept_note a WHERE a.owner_id = #{owner} AND (a.concept_id = #{id} OR a.note_id = #{id})
SELECT r.id, 'SEMANTIC' kind, IF(r.source_id = #{id}, r.target_id, r.source_id) item_id, r.relation_type, IF(r.relation_type IN ('RELATED','CONTRASTS'), 'BOTH', IF(r.source_id = #{id}, 'OUT', 'IN')) direction, NULL source_version_id, NULL source_version_number, NULL line_start, NULL line_end, NULL excerpt FROM knowledge_relation r WHERE r.owner_id = #{owner} AND (r.source_id = #{id} OR r.target_id = #{id})
SELECT r.id, #{type} kind, r.target_item_idr.source_item_id item_id, NULL relation_type, 'OUT''IN' direction, r.source_version_id, r.source_version_number, r.line_start, r.line_end, r.excerpt FROM knowledge_reference r JOIN knowledge_item source ON source.owner_id = r.owner_id AND source.id = r.source_item_id AND source.current_version_id = r.source_version_id WHERE r.owner_id = #{owner} AND r.source_item_id = #{id}AND r.target_item_id = #{id} AND r.source_item_id <> #{id}
) c JOIN knowledge_item i ON i.id = c.item_id AND i.owner_id = #{owner} JOIN knowledge_version v ON v.id = i.current_version_id AND v.item_id = i.id AND v.owner_id = i.owner_id WHERE c.id > #{cursor} ORDER BY c.id LIMIT #{limit}

SELECT v.id,v.item_id,v.version_number,v.body FROM knowledge_version v
WHERE v.owner_id = #{owner} AND NOT EXISTS (SELECT 1 FROM knowledge_reference_scan s WHERE s.version_id = v.id)
ORDER BY v.id LIMIT #{limit}
